import numpy as np,pandas as pd,joblib,json,os,hashlib
from sklearn.pipeline import make_pipeline
from sklearn.preprocessing import StandardScaler
from sklearn.linear_model import LogisticRegression
from sklearn.metrics import balanced_accuracy_score,accuracy_score,confusion_matrix
root='/root/nailfold'; base='/root/autodl-tmp/nailfold/artifacts/features'; man=pd.read_csv(root+'/artifacts/manifest/locked_evaluation_v1_reviewed.csv'); dev=man[(man.evaluation_role=='development') & man.microthrombus.isin(['无','1--2','>2'])]; idx=pd.read_csv(base+'/dinov2/index.csv'); F=np.load(base+'/dinov2/features.npy').astype('float32'); X=pd.DataFrame(F,index=idx.exam_case_id).groupby(level=0).mean(); dev=dev[dev.exam_case_id.isin(X.index)]; y=(dev.microthrombus!='无').astype(int).to_numpy(); model=make_pipeline(StandardScaler(),LogisticRegression(C=.1,class_weight='balanced',max_iter=3000));model.fit(X.loc[dev.exam_case_id],y); out=root+'/artifacts/experiments/microthrombus_dino_binary_20260916';os.makedirs(out,exist_ok=True);joblib.dump(model,out+'/model.joblib'); li=pd.read_csv(base+'/dinov2_locked/index.csv'); lf=np.load(base+'/dinov2_locked/features.npy').astype('float32'); LX=pd.DataFrame(lf,index=li.exam_case_id).groupby(level=0).mean(); pred=model.predict(LX); truth=man.set_index('exam_case_id').loc[LX.index,'microthrombus']; ok=truth.isin(['无','1--2','>2']); yy=(truth[ok]!='无').astype(int); ev={'development_n':len(dev),'locked_n':int(ok.sum()),'locked_accuracy':accuracy_score(yy,pred[ok]),'locked_balanced_accuracy':balanced_accuracy_score(yy,pred[ok]),'locked_confusion_matrix':confusion_matrix(yy,pred[ok],labels=[0,1]).tolist(),'locked_test_used_for_training':False,'feature_source':'DINOv2 case mean only','status':'candidate_requires_external_validation'};json.dump(ev,open(out+'/evaluation.json','w'),indent=2);print(json.dumps(ev))
